#!/usr/bin/env python3
"""Generate a bounded human review packet from recorded evidence; never label it."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
EV = ROOT / 'eval'


def read(path):
    return json.loads(path.read_text()) if path.exists() else None


def main():
    ground = sorted((read(p) for p in (EV / 'ground-truth').glob('*.json')), key=lambda x: x['pr'])
    out = ['# Human review packet', '',
           'Pending independent human review. All existing judgements below are from agents.',
           'Generated by `python3 change-risk-research/harness/prepare_human_review.py`.', '',
           'Start with the 12 defect cases, then the disputed C findings and three low-risk controls.',
           'Use the linked source only when a mechanism or label needs checking; no transcript reading is required.', '',
           'For each case/finding, record: ground truth **correct / incorrect / uncertain**; impact',
           '**appropriate / overstated / understated**; finding **valid / invalid / uncertain**;',
           'material new insight **yes / no**; actionable recommendation **yes / no**.',
           'Leave answers blank until a human reviews. Link the evidence supporting corrections.', '',
           '## Known-defect cases', '']
    for g in ground:
        if g['outcome'] != 'defect':
            continue
        pr = g['pr']; cid = f'stack-{pr}'
        condition = 'C' if (EV / f'change-risk/results/C/{cid}-r1/assessment.json').exists() else 'B'
        assessment_path = f'../eval/change-risk/results/{condition}/{cid}-r1/assessment.json'
        a = read(ROOT / 'docs' / assessment_path)
        adj = read(EV / f'adjudication/change-risk/{condition}/{cid}.json')
        out += [f'### [PR #{pr}](https://github.com/cipherstash/stack/pull/{pr}) — {g["expert_impact"]}', '',
                f'[Ground truth](../eval/ground-truth/{pr}.json) · [assessment ({condition})]({assessment_path})', '']
        for kd in g['known_defects']:
            detections = []
            for cond in "ABC":
                labels = read(EV / f'adjudication/change-risk/{cond}/{cid}.json')
                if labels:
                    hits = [f['id'] for f in labels['findings'] if kd['id'] in f.get('matches', []) and f['label'] == 'match']
                    detections.append(cond + ': ' + (', '.join(hits) if hits else 'miss'))
            fixes = ' · '.join(f'[fix evidence {i+1}]({url if url.startswith("http") else "https://github.com/cipherstash/stack/commit/" + url})' for i, url in enumerate(kd.get('evidence', [])))
            out += [f'- **{kd["id"]}:** {kd["description"]} Mechanism: {kd.get("mechanism", "See ground truth")}. '
                    f'Detected in recorded run 1: {"; ".join(detections)}'
                    + (' (post-hoc ground truth; excluded from headline recall)' if kd.get('added_post_hoc') else '')
                    + f'. {fixes}']
        if a:
            ranked = sorted(a['failure_scenarios'], key=lambda x: {'critical': 4, 'high': 3, 'medium': 2, 'low': 1}.get(x['impact'], 0), reverse=True)
            extra = [f for f in ranked if not any(j['id'] == f['id'] and j['label'] == 'match' for j in (adj or {}).get('findings', []))][:1]
            for f in extra:
                out += [f'- Additional risk to inspect ({f["id"]}, {f["basis"]}): **{f["title"]}**. {f["mechanism"]}']
        out += ['', 'Human: ground truth ___; impact ___; finding ___; new insight ___; actionable ___; notes ___', '']
    out += ['## Disputed material findings (condition C)', '',
            'These are disagreements, not resolved labels. The complete disagreement index (including A/B and historical CodeRabbit) is in [agreement.json](../eval/agreement.json); this bounded packet prioritizes condition C.', '']
    for p in sorted((EV / 'adjudication/change-risk/C').glob('*.json')):
        first = read(p); second = read(EV / 'adjudication-blind/change-risk/C' / p.name)
        if not second:
            continue
        by_id = {f['id']: f for f in second['findings']}
        a = read(EV / f'change-risk/results/C/{p.stem}-r1/assessment.json')
        titles = {f['id']: f['title'] for f in a['failure_scenarios']}
        for f in first['findings']:
            b = by_id.get(f['id'])
            if b and f['label'] != b['label']:
                out += [f'- [{p.stem} {f["id"]}](../eval/change-risk/results/C/{p.stem}-r1/assessment.json): '
                        f'{titles.get(f["id"], "")} — {f["label"]} → {b["label"]}. '
                        f'[first reasons](../eval/adjudication/change-risk/C/{p.name}); '
                        f'[second reasons](../eval/adjudication-blind/change-risk/C/{p.name}). Human finding ___; new insight ___; actionable ___']
    out += ['', '## Low-confidence ground truth', '',
            'Review these impact assumptions; low confidence is explicitly recorded by the original agent.', '']
    for g in ground:
        if g.get('impact_confidence') == 'low':
            out += [f'- [#{g["pr"]}](https://github.com/cipherstash/stack/pull/{g["pr"]}) '
                    f'[record](../eval/ground-truth/{g["pr"]}.json): {g["expert_impact"]}. Human ground truth ___; impact ___']
    out += ['', '## Low-risk control sample', '']
    for g in [g for g in ground if g['expert_impact'] == 'low' and g['outcome'] != 'defect'][:3]:
        pr = g['pr']; cid = f'stack-{pr}'
        cond = 'C' if (EV / f'change-risk/results/C/{cid}-r1/assessment.json').exists() else 'B'
        out += [f'- [#{pr}](https://github.com/cipherstash/stack/pull/{pr}) · [ground truth](../eval/ground-truth/{pr}.json) · '
                f'[assessment](../eval/change-risk/results/{cond}/{cid}-r1/assessment.json): {g["rationale"]} '
                'Human ground truth ___; impact ___; finding ___; new insight ___; actionable ___']
    (ROOT / 'docs/human-review.md').write_text('\n'.join(out) + '\n')


if __name__ == '__main__':
    main()
